import { BrowserPlatform } from './browser';
import { CONFIGURED_LINKS, configuredAddress } from './configured-links';
import { LOCALE_PATHS, type LocalePaths, pathInLocale, pathOfUrl } from './locale-paths';
import { SessionService } from './session';
import { CARD_FILE_NAME, CARD_HEIGHT, CARD_WIDTH } from './social-card';
import { MessageTitleStrategy } from './title';

/** Replaced by the build with the site's origin (`CRUFTFREE_SITE_ORIGIN`). */
