const ROBOTS_INDEX = 'index, follow';
const ROBOTS_NOINDEX = 'noindex, nofollow';
const MANAGED_LINK = 'data-cruftfree-site';
const X_DEFAULT = 'x-default';

/** The image a page is shared with. */
