  readonly keywordKeys: readonly string[];
  /** The configured address the page names as its canonical one, or `null` for its own URL. */
  readonly canonicalLink: string | null;
  /** Whether the description fills its message from the page's values: the page writes it (`keepPageHead`). */
  readonly descriptionFromPage: boolean;
